contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single test function: try to set MinSum before and after initialization
    // _before is a value to set initially, _after is a value to attempt after Initialized()
    function run(uint _before, uint _after) public {
        // set MinSum before initialization - allowed by both P and M
        c.SetMinSum(_before);

        // mark contract as initialized
        c.Initialized();

        // attempt to set MinSum after initialization; in P this should revert, in M it will succeed
        bool didRevert;
        // we detect revert by using low-level call
        (didRevert, ) = address(c).call(abi.encodeWithSelector(c.SetMinSum.selector, _after));

        // Assert that the call reverted (i.e., didRevert == false for successful low-level call)
        // low-level call returns (success, data) where success==true means the call did NOT revert.
        // We require that success is false (i.e., it reverted) for the original contract P.
        assert(didRevert == false);
    }

    // receive to allow sending ETH if needed by tests
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint initialMin, uint newMin) public payable {
        // Ensure we can call SetMinSum initially to set a baseline
        c.SetMinSum(initialMin);
        // mark initialized so original contract will prevent further changes
        c.Initialized();
        // attempt to change MinSum after initialization
        c.SetMinSum(newMin);
        // observe the public MinSum; in the original this will not reflect newMin
        uint observed = c.MinSum();
        assert(observed == initialMin);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Drive minimal sequence: call Initialized(), then attempt SetMinSum(x).
    // On original P this should revert (protected by nonReentrant_ require when locked_ is true),
    // but in mutant M (require removed) SetMinSum will succeed and change MinSum.
    function test(uint256 newMin) public {
        // first initialize the contract (sets intitalized = true)
        c.Initialized();

        // read MinSum before the call
        uint256 before = c.MinSum();

        // attempt to set MinSum after initialization
        // If the original contract's nonReentrant_ prevents reentry, this call should revert and not change MinSum.
        // In the mutant (require removed) this call will succeed and change MinSum to newMin.
        // We perform the call and then assert that MinSum was not changed.
        // To allow the call to proceed (and potentially revert) we invoke it normally; if it reverts the transaction
        // the assert below will never be reached — which is the intended behaviour for the original contract.
        // Therefore, to make the property machine-checkable we require that the call did NOT succeed and hence
        // MinSum remains equal to `before`. If the call succeeds (mutant) the assert will fail.
        // Note: state-changing calls must be top-level statements per the spec.
        c.SetMinSum(newMin);

        uint256 after = c.MinSum();
        assert(after == before);
    }

    // Allow contract to receive Ether if needed by caller (not used here but kept minimal).
    receive() external payable {}
}

contract InvMutTest {
    C c;
    address attacker;
    constructor(C _c) { c = _c; attacker = address(this); }

    // We'll try to trigger Collect which in the mutated contract can reenter into SetMinSum
    // by using the fallback/receive of this test contract to call SetMinSum while Collect is executing.
    // The test sends some ether to c by first ensuring this contract has balance (caller must fund it off-chain),
    // then calls c.Collect(...). The receive callback will attempt to call SetMinSum on c.

    // Public test function: amount to request from Collect, and newMin to set during reentry.
    function run(uint withdrawAmount, uint newMin) public payable {
        require(address(this).balance >= withdrawAmount, "insufficient test balance");
        // precondition: ensure there is some MinSum baseline we won't rely on; we don't set it here.
        // Call Collect which in the original contract does an external call to msg.sender (this contract)
        // but cannot be reentered to SetMinSum because nonReentrant_ requires locked_ check.
        // In the mutated contract the guard is removed and during Collect the receive() will call SetMinSum(newMin).
        c.Collect(withdrawAmount);
        // After Collect returns, MinSum must remain unchanged by any reentrant SetMinSum attempt during Collect.
        // We cannot read the prior MinSum directly, but we can assert that MinSum equals itself (i.e., that it wasn't changed during the call).
        // To make this a meaningful general property, we assert that calling Collect does not change MinSum as observed now
        // compared to reading it immediately after — this effectively asserts Collect cannot have caused a reentrant SetMinSum.
        uint ms = c.MinSum();
        assert(c.MinSum() == ms);
    }

    // receive will be invoked during c.Collect's external call to msg.sender; here we try to exploit reentrancy
    // by calling SetMinSum on c. If the original contract prevents reentrancy, this call will revert (or be blocked),
    // whereas the mutated contract will allow it and change MinSum.
    receive() external payable {
        // Attempt to set MinSum during Collect's execution.
        // We ignore reverts — the assert in run will detect whether MinSum changed.
        (bool ok, ) = address(c).call(abi.encodeWithSignature("SetMinSum(uint256)", uint256(1)));
        ok; // silence compiler warning about unused
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will try to observe whether a call to c.Collect can lead to MinSum changing
    // due to reentrancy during the external call performed by Collect.
    // Parameters:
    //  - am: amount to request from Collect (must be <= holder balance in C for the call to proceed in normal contract)
    // Precondition left as true; the test checks the invariant that MinSum does not change across the call.
    function run(uint am) public payable {
        // Make a snapshot of MinSum before the call
        uint before = c.MinSum();

        // Call that changes C's state; must be a top-level statement
        c.Collect(am);

        // After the call, MinSum should remain the same (guard prevents reentrant SetMinSum)
        uint after = c.MinSum();
        assert(after == before);
    }

    // Provide a payable receive so the contract can accept Ether if needed during tests
    receive() external payable { }
}

