pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker atk;

    function setUp() public { 
        c = new C();
        atk = new Attacker(address(c));
    }

    // fuzzed params: amount to deposit and a candidate newMin to be set during reentry
    function testFuzz_property(uint256 deposit, uint256 newMin) public {
        // keep amounts in a reasonable wide domain
        deposit = bound(deposit, 1, 1 ether);
        newMin = bound(newMin, 0, 1 ether);

        // fund attacker and set initial conditions
        vm.deal(address(atk), deposit + 1 wei);

        // Initialize MinSum to a known value via owner-like call sequence:
        // The contract requires SetMinSum only when not intitalized; use a fresh contract so it is allowed.
        // Call SetLogFile to set the LogFile to some address (use attacker address harmlessly)
        vm.prank(address(this));
        c.SetLogFile(address(atk));

        vm.prank(address(this));
        c.SetMinSum(0);

        // Now mark initialized so later SetMinSum would revert unless nonReentrant prevents it
        vm.prank(address(this));
        c.Initialized();

        // Deposit into attacker's holder via attacker fallback which will reenter Collect path
        // Attacker will set desired newMin during reentrancy when Collect is executing
        atk.setNewMin(newMin);

        // deposit into c by calling Put (via fallback or direct). Use prank from attacker
        vm.startPrank(address(atk));
        // send deposit to Put via fallback
        (bool sent, ) = address(c).call{value: deposit}(abi.encodeWithSignature("Put(uint256)", 0));
        require(sent);
        vm.stopPrank();

        // Ensure attacker has sufficient balance recorded and lock time passed so Collect proceeds
        // fast forward time
        vm.warp(block.timestamp + 1 days);

        // Now perform Collect from attacker which during the external call will trigger reentrancy to SetMinSum
        vm.startPrank(address(atk));
        // call Collect for some amount <= deposit
        uint256 collectAmt = 1 wei;
        // execute; may succeed or revert depending on mutant; we don't require success here
        (bool ok, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", collectAmt));
        vm.stopPrank();

        // The reference contract guarantees MinSum unchanged (it was set to 0). The mutant that removed the
        // require in nonReentrant_ allows reentrancy to call SetMinSum and change MinSum to newMin.
        // Assert that MinSum is still 0 (this holds for the reference for all inputs; will fail for mutant for some inputs)
        assertTrue(c.MinSum() == 0);
    }
}

// Attacker contract: during Collect it will be sent ether via call, and in its receive it will call SetMinSum on c
contract Attacker {
    address public target;
    uint256 public newMin;

    constructor(address _t) payable {
        target = _t;
    }

    function setNewMin(uint256 _m) public {
        newMin = _m;
    }

    // When receiving funds during Collect, reenter target to call SetMinSum
    receive() external payable {
        // attempt to call SetMinSum on target; this will succeed only if nonReentrant guard is broken
        (bool s, ) = target.call(abi.encodeWithSignature("SetMinSum(uint256)", newMin));
        s; // ignore result
    }
}

