pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz parameters: attacker initial deposit and newMin value to try to set via reentrancy
    function testFuzz_property(uint256 deposit, uint256 newMin) public {
        // Keep deposit reasonable and non-zero so calls succeed and gas isn't absurd
        deposit = bound(deposit, 1, 1 ether);
        // newMin can be any uint but bound to a small range to avoid extremes
        newMin = bound(newMin, 0, type(uint256).max);

        // deploy attacker, fund it
        Attacker attacker = new Attacker(address(c));
        vm.deal(address(attacker), deposit);

        // Initialize contract: set a starting MinSum to a distinct value
        uint256 initialMin = 123;
        c.SetMinSum(initialMin);
        // initialize log file to a simple Log deployed here
        LogHelper log = new LogHelper();
        c.SetLogFile(address(log));
        // mark contract initialized so SetMinSum/SetLogFile can't be called later unless reentrancy allows
        c.Initialized();

        // The attacker will deposit funds and then call Collect which during the external call will re-enter
        // into c.SetMinSum(newMin). This should be prevented by the reference but allowed in the mutant.

        // give attacker an unlockTime by calling Put with 0 (via fallback or direct)
        // Put is payable; call Put to set balance and unlockTime
        vm.prank(address(attacker));
        attacker.prepareAndPut{value: deposit}();

        // Ensure holder's unlockTime is in the past so Collect's time check passes
        // We cannot directly manipulate block.timestamp much; but Set the unlockTime small and warp forward
        vm.warp(block.timestamp + 1);

        // Now attempt to Collect: this will trigger attacker.receive which re-enters SetMinSum(newMin)
        bool ok;
        try attacker.triggerCollect{value: 0}(newMin) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property we assert: after this sequence, in the reference MinSum must remain equal to initialMin
        // The mutant (without require in nonReentrant_) will allow reentrant SetMinSum and thus MinSum may change.
        assertTrue(c.MinSum() == initialMin);
    }
}

// Minimal attacker that re-enters SetMinSum during a low-level external call path used in Collect
contract Attacker {
    C public target;
    uint256 public desiredMin;

    constructor(address _t) {
        target = C(_t);
    }

    // Prepare funds and call Put on the victim contract to create a Holder entry
    function prepareAndPut() external payable {
        // call Put(0)
        target.Put{value: msg.value}(0);
    }

    // Called by the test to start the Collect which will result in a low-level call to this contract
    function triggerCollect(uint256 _newMin) external payable {
        desiredMin = _newMin;
        // attempt to Collect the full balance; Collect requires calling from the holder address
        // so we call Collect as this attacker
        target.Collect{value: 0}(address(this).balance);
    }

    // Receive is invoked by C's low-level call in Collect; here we re-enter SetMinSum
    receive() external payable {
        // Re-enter to attempt to change MinSum
        // Use a try/catch to avoid bubbling reverts to the victim
        try target.SetMinSum(desiredMin) {
            // ignore
        } catch {
            // ignore failures
        }
    }
}

// Minimal Log helper so SetLogFile can be set; mirrors the original Log.AddMessage signature
contract LogHelper {
    struct Message { address Sender; string Data; uint Val; uint Time; }
    Message[] public History;
    Message LastMsg;
    function AddMessage(address _adr,uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}

