// Minimal attacker that re-enters: its fallback calls back into c.SetMinSum to try to change MinSum.
contract Attacker {
    address target;
    constructor(address _t) payable {
        target = _t;
    }
    // fallback invoked when funded in test; it will call address(target).call to invoke Put via fallback
    fallback() external payable {
        // Do a no-op; the test initiates Put by sending to this contract, which in turn doesn't need to do more.
    }
    receive() external payable {
        // during Collect in the target, if reentrancy were possible, an attacker would call SetMinSum
        // Try to change MinSum to zero (this will succeed only on mutant lacking the require)
        (bool s, ) = target.call(abi.encodeWithSignature("SetMinSum(uint256)", 0));
        s; // ignore result
    }
}

