pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: deposit amount and collect amount; attacker is a deployed helper whose address is fixed
    function testFuzz_property(uint256 deposit, uint256 collectAmt) public {
        // keep amounts in a reasonable wide domain but nonzero for meaningful deposits
        deposit = bound(deposit, 1, type(uint128).max);
        collectAmt = bound(collectAmt, 1, type(uint128).max);

        // deploy attacker helper that will re-enter during Collect to call SetMinSum
        ReentrantAttacker attacker = new ReentrantAttacker(address(c));

        // fund attacker and set it up as the caller
        vm.deal(address(attacker), deposit);

        // Attacker puts funds and sets an unlockTime in the past so Collect can proceed
        attacker.doPut{value: deposit}(0);

        // ensure MinSum initially is some value different than what attacker will try to set
        // attacker will attempt to set MinSum to 1 via SetMinSum; ensure initial MinSum != 1
        // If initial equals 1, set to 2 using a harmless call via attacker (only allowed before initialization)
        if (c.MinSum() == 1) {
            // SetMinSum guarded by nonReentrant_ and intitalized flag; contract allows SetMinSum only if !intitalized
            // We call SetMinSum once (no reentrancy) via attacker to set to 2
            attacker.callSetMinSum(2);
            assert(c.MinSum() == 2);
        }

        uint before = c.MinSum();

        // Now attempt to Collect from attacker; during Collect the attacker will re-enter and attempt SetMinSum(1)
        // We run the call as the attacker contract
        attacker.doCollect{value: 0}(collectAmt);

        uint after = c.MinSum();

        // The general rule: reference contract's nonReentrant_ prevents reentrant SetMinSum, so MinSum must be unchanged.
        // The mutant removing the require allows MinSum to be changed by the reentrant SetMinSum call during Collect.
        assertTrue(before == after);
    }
}

// Minimal re-entrant attacker that will call SetMinSum from its receive() during Collect
contract ReentrantAttacker {
    C public target;
    bool public reentered;

    constructor(address _t) {
        target = C(_t);
        reentered = false;
    }

    // helper to call Put on target
    function doPut(uint _lockTime) external payable {
        (bool ok, ) = address(target).call{value: msg.value}(abi.encodeWithSelector(target.Put.selector, _lockTime));
        require(ok);
    }

    // helper to call Collect on target which will trigger receive fallback if value sent — here no value
    function doCollect(uint _am) external payable {
        // call Collect externally so target will call back to this contract when sending value
        target.Collect(_am);
    }

    // helper to call SetMinSum when not reentrant needed
    function callSetMinSum(uint _v) external {
        target.SetMinSum(_v);
    }

    // receive is used to attempt reentrancy: when target sends value to this contract during Collect,
    // try to call SetMinSum(1). On reference contract this will be blocked by nonReentrant_ require.
    receive() external payable {
        if (!reentered) {
            reentered = true;
            // attack: try to change MinSum to 1 during Collect
            // ignore success/failure — mutant will allow this to succeed
            // use low-level call to avoid bubbling reverts
            (bool s, ) = address(target).call(abi.encodeWithSelector(target.SetMinSum.selector, 1));
            s; // swallow
        }
    }
}

