pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameter: any uint to attempt to set MinSum
    function testFuzz_property(uint256 newMin) public {
        // Keep domain wide but avoid trivial overflow issues (none here)
        // 1) Before initialization, SetMinSum should succeed and set MinSum to newMin
        bool ok;
        try c.SetMinSum(newMin) { ok = true; } catch { ok = false; }
        // on reference this should succeed for any newMin
        assertTrue(ok);
        assertTrue(c.MinSum() == newMin);

        // 2) Initialize the contract
        c.Initialized();

        // 3) After initialization, the reference MUST revert when calling SetMinSum again.
        //    The mutant removed that revert, so for some fuzzed newMin this will succeed and change MinSum.
        bool ok2;
        try c.SetMinSum(newMin + 1) { ok2 = true; } catch { ok2 = false; }

        // Single assertion: on the reference, the second call must revert (ok2 == false) for ALL admissible inputs.
        assertTrue(!ok2);
    }
}
